Literal.Value:
'{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "description": "Ranking Top N de municipios por focos de queimada. Pensado para RLS por estado: com um unico estado no contexto o nome do estado vai no titulo; com varios, a sigla aparece no rotulo. Mostra participacao no total, concentracao do Top N e destaque de selecao.",
 "padding": 0,
 "config": {
  "view": {
   "stroke": null
  },
  "text": {
   "font": "Din"
  }
 },
 "data": [
  {
   "name": "dataset"
  },
  {
   "name": "siglas",
   "values": [
    {
     "key": "acre",
     "sigla": "AC"
    },
    {
     "key": "alagoas",
     "sigla": "AL"
    },
    {
     "key": "amazonas",
     "sigla": "AM"
    },
    {
     "key": "amapá",
     "sigla": "AP"
    },
    {
     "key": "bahia",
     "sigla": "BA"
    },
    {
     "key": "ceará",
     "sigla": "CE"
    },
    {
     "key": "espírito santo",
     "sigla": "ES"
    },
    {
     "key": "goiás",
     "sigla": "GO"
    },
    {
     "key": "maranhão",
     "sigla": "MA"
    },
    {
     "key": "minas gerais",
     "sigla": "MG"
    },
    {
     "key": "mato grosso do sul",
     "sigla": "MS"
    },
    {
     "key": "mato grosso",
     "sigla": "MT"
    },
    {
     "key": "pará",
     "sigla": "PA"
    },
    {
     "key": "paraíba",
     "sigla": "PB"
    },
    {
     "key": "pernambuco",
     "sigla": "PE"
    },
    {
     "key": "piauí",
     "sigla": "PI"
    },
    {
     "key": "paraná",
     "sigla": "PR"
    },
    {
     "key": "rio de janeiro",
     "sigla": "RJ"
    },
    {
     "key": "rio grande do norte",
     "sigla": "RN"
    },
    {
     "key": "rondônia",
     "sigla": "RO"
    },
    {
     "key": "roraima",
     "sigla": "RR"
    },
    {
     "key": "rio grande do sul",
     "sigla": "RS"
    },
    {
     "key": "santa catarina",
     "sigla": "SC"
    },
    {
     "key": "sergipe",
     "sigla": "SE"
    },
    {
     "key": "são paulo",
     "sigla": "SP"
    },
    {
     "key": "tocantins",
     "sigla": "TO"
    },
    {
     "key": "distrito federal",
     "sigla": "DF"
    }
   ]
  },
  {
   "name": "rows",
   "source": "dataset",
   "transform": [
    {
     "type": "formula",
     "as": "estadoTxt",
     "expr": "isValid(datum[''estado'']) ? datum[''estado''] : ''''"
    },
    {
     "type": "formula",
     "as": "muniTxt",
     "expr": "isValid(datum[''municipio'']) ? datum[''municipio''] : ''''"
    },
    {
     "type": "formula",
     "as": "key",
     "expr": "lower(datum.estadoTxt)"
    },
    {
     "type": "formula",
     "as": "fullLabel",
     "expr": "datum.muniTxt + '' · '' + datum.estadoTxt"
    },
    {
     "type": "formula",
     "as": "focos",
     "expr": "datum[''Total de Focos'']"
    },
    {
     "type": "filter",
     "expr": "isValid(datum.focos) && datum.focos > 0 && length(datum.muniTxt) > 0"
    },
    {
     "type": "collect",
     "sort": {
      "field": [
       "focos",
       "fullLabel"
      ],
      "order": [
       "descending",
       "ascending"
      ]
     }
    },
    {
     "type": "window",
     "ops": [
      "row_number"
     ],
     "as": [
      "rank"
     ]
    }
   ]
  },
  {
   "name": "tot",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "fields": [
      "focos",
      "focos",
      "focos",
      "estadoTxt",
      "estadoTxt"
     ],
     "ops": [
      "sum",
      "count",
      "max",
      "distinct",
      "max"
     ],
     "as": [
      "total",
      "n",
      "maxF",
      "nEstados",
      "estadoUnico"
     ]
    },
    {
     "type": "formula",
     "as": "totalText",
     "expr": "datum.total >= 1000000 ? pbiFormat(datum.total / 1000000, ''#,0.00'') + '' Mi'' : (datum.total >= 1000 ? pbiFormat(datum.total / 1000, ''#,0.0'') + '' Mil'' : pbiFormat(datum.total, ''#,0''))"
    },
    {
     "type": "filter",
     "expr": "datum.n > 0"
    }
   ]
  },
  {
   "name": "top",
   "source": "rows",
   "transform": [
    {
     "type": "filter",
     "expr": "datum.rank <= nShow"
    },
    {
     "type": "lookup",
     "from": "siglas",
     "key": "key",
     "fields": [
      "key"
     ],
     "values": [
      "sigla"
     ],
     "as": [
      "uf"
     ]
    },
    {
     "type": "formula",
     "as": "listLabel",
     "expr": "datum.muniTxt + (nEstados > 1 ? '' · '' + (isValid(datum.uf) ? datum.uf : datum.estadoTxt) : '''')"
    },
    {
     "type": "formula",
     "as": "share",
     "expr": "datum.focos / data(''tot'')[0].total"
    },
    {
     "type": "formula",
     "as": "vsLeader",
     "expr": "datum.focos / data(''tot'')[0].maxF"
    },
    {
     "type": "formula",
     "as": "shareText",
     "expr": "pbiFormat(datum.share, ''0.0%'')"
    },
    {
     "type": "formula",
     "as": "valueText",
     "expr": "datum.focos >= 1000000 ? pbiFormat(datum.focos / 1000000, ''#,0.00'') + '' Mi'' : (datum.focos >= 1000 ? pbiFormat(datum.focos / 1000, ''#,0.0'') + '' Mil'' : pbiFormat(datum.focos, ''#,0''))"
    }
   ]
  },
  {
   "name": "topAgg",
   "source": "top",
   "transform": [
    {
     "type": "aggregate",
     "fields": [
      "focos"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "topSum"
     ]
    }
   ]
  },
  {
   "name": "foot",
   "source": "topAgg",
   "transform": [
    {
     "type": "formula",
     "as": "text",
     "expr": "nShow >= nItems ? ''Total: '' + data(''tot'')[0].totalText + '' focos em '' + nItems + (nItems === 1 ? '' município'' : '' municípios'') : ''Top '' + nShow + '' concentram '' + pbiFormat(datum.topSum / data(''tot'')[0].total, ''0.0%'') + '' dos '' + data(''tot'')[0].totalText + '' focos''"
    },
    {
     "type": "filter",
     "expr": "nItems > 0"
    }
   ]
  },
  {
   "name": "emptyState",
   "values": [
    {
     "k": 1
    }
   ],
   "transform": [
    {
     "type": "filter",
     "expr": "length(data(''rows'')) === 0"
    }
   ]
  }
 ],
 "signals": [
  {
   "name": "cText",
   "value": "#F4F6F8"
  },
  {
   "name": "cTextMuted",
   "value": "#AEB6C2"
  },
  {
   "name": "cSurface",
   "value": "#15191F"
  },
  {
   "name": "cSurface2",
   "value": "#1D232B"
  },
  {
   "name": "cBorder",
   "value": "#2A323C"
  },
  {
   "name": "cAccent",
   "value": "#5BC0EB"
  },
  {
   "name": "maxTop",
   "value": 10
  },
  {
   "name": "fs",
   "update": "max(0.8, min(1.15, min(width / 480, height / 300)))"
  },
  {
   "name": "pad",
   "update": "max(12, min(20, width * 0.035))"
  },
  {
   "name": "gap",
   "update": "max(6, 8 * fs)"
  },
  {
   "name": "radius",
   "update": "max(10, min(18, height * 0.08))"
  },
  {
   "name": "fsTitle",
   "update": "max(10.5, 11 * fs)"
  },
  {
   "name": "fsRow",
   "update": "max(11, 12 * fs)"
  },
  {
   "name": "fsMicro",
   "update": "max(10, 10.5 * fs)"
  },
  {
   "name": "nItems",
   "update": "data(''tot'')[0] ? data(''tot'')[0].n : 0"
  },
  {
   "name": "nEstados",
   "update": "data(''tot'')[0] ? data(''tot'')[0].nEstados : 0"
  },
  {
   "name": "estadoUnico",
   "update": "data(''tot'')[0] ? data(''tot'')[0].estadoUnico : ''''"
  },
  {
   "name": "multiState",
   "update": "nEstados > 1"
  },
  {
   "name": "showShare",
   "update": "width >= 380"
  },
  {
   "name": "showFooter",
   "update": "height >= 190"
  },
  {
   "name": "innerW",
   "update": "max(0, width - 2 * pad)"
  },
  {
   "name": "headerH",
   "update": "fsTitle + 12"
  },
  {
   "name": "footerH",
   "update": "showFooter ? fsMicro + 14 : 0"
  },
  {
   "name": "topY",
   "update": "pad + headerH"
  },
  {
   "name": "availH",
   "update": "max(0, height - topY - pad - footerH)"
  },
  {
   "name": "nShow",
   "update": "max(1, min(maxTop, min(nItems, floor(availH / (22 * fs)))))"
  },
  {
   "name": "rowH",
   "update": "min(availH / nShow, 36 * fs)"
  },
  {
   "name": "barH",
   "update": "max(6, min(14, rowH * 0.36))"
  },
  {
   "name": "rankW",
   "update": "fsRow * 1.9"
  },
  {
   "name": "valueW",
   "update": "fsRow * 5.0"
  },
  {
   "name": "shareW",
   "update": "showShare ? fsMicro * 4.6 + gap : 0"
  },
  {
   "name": "labelW",
   "update": "max(64, min(200, innerW * (multiState ? 0.40 : 0.34)))"
  },
  {
   "name": "valueRightX",
   "update": "width - pad - shareW"
  },
  {
   "name": "barX0",
   "update": "pad + rankW + labelW + gap"
  },
  {
   "name": "barX1",
   "update": "max(barX0 + 20, valueRightX - valueW - gap)"
  }
 ],
 "scales": [
  {
   "name": "xb",
   "type": "linear",
   "zero": true,
   "nice": false,
   "domain": {
    "data": "tot",
    "field": "maxF"
   },
   "range": [
    {
     "signal": "barX0"
    },
    {
     "signal": "barX1"
    }
   ]
  }
 ],
 "marks": [
  {
   "name": "shadow",
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 3
     },
     "y": {
      "value": 3
     },
     "width": {
      "signal": "max(0, width - 3)"
     },
     "height": {
      "signal": "max(0, height - 3)"
     },
     "cornerRadius": {
      "signal": "radius"
     },
     "fill": {
      "value": "#000000"
     },
     "fillOpacity": {
      "value": 0.28
     }
    }
   }
  },
  {
   "name": "surface",
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "value": 0
     },
     "width": {
      "signal": "max(0, width - 3)"
     },
     "height": {
      "signal": "max(0, height - 3)"
     },
     "cornerRadius": {
      "signal": "radius"
     },
     "fill": {
      "signal": "cSurface"
     },
     "stroke": {
      "signal": "cBorder"
     },
     "strokeWidth": {
      "value": 1
     }
    }
   }
  },
  {
   "name": "title",
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "pad"
     },
     "text": {
      "signal": "nItems > 0 ? (nShow >= nItems ? ''FOCOS POR MUNICÍPIO'' : ''TOP '' + nShow + (nShow === 1 ? '' MUNICÍPIO'' : '' MUNICÍPIOS'')) + (nEstados === 1 ? '' · '' + upper(estadoUnico) : '''') : (length(data(''dataset'')) > 0 ? '''' : ''FOCOS DE QUEIMADA'')"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsTitle"
     },
     "fontWeight": {
      "value": 600
     },
     "limit": {
      "signal": "max(0, valueRightX - fsRow * 3 - pad)"
     }
    }
   }
  },
  {
   "name": "headFocos",
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "valueRightX"
     },
     "y": {
      "signal": "pad"
     },
     "text": {
      "signal": "nItems > 0 ? ''FOCOS'' : ''''"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     },
     "fontWeight": {
      "value": 600
     }
    }
   }
  },
  {
   "name": "headShare",
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "width - pad"
     },
     "y": {
      "signal": "pad"
     },
     "text": {
      "signal": "nItems > 0 && showShare ? ''%'' : ''''"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "top"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     },
     "fontWeight": {
      "value": 600
     }
    }
   }
  },
  {
   "name": "tracks",
   "type": "rect",
   "from": {
    "data": "top"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "barX0"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH + rowH / 2 - barH / 2"
     },
     "width": {
      "signal": "max(0, barX1 - barX0)"
     },
     "height": {
      "signal": "barH"
     },
     "cornerRadius": {
      "signal": "barH / 2"
     },
     "fill": {
      "signal": "cSurface2"
     }
    }
   }
  },
  {
   "name": "bars",
   "type": "rect",
   "from": {
    "data": "top"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "barX0"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH + rowH / 2 - barH / 2"
     },
     "width": {
      "signal": "max(3, scale(''xb'', datum.focos) - barX0)"
     },
     "height": {
      "signal": "barH"
     },
     "cornerRadius": {
      "signal": "barH / 2"
     },
     "fill": {
      "signal": "cAccent"
     },
     "fillOpacity": {
      "signal": "datum.__selected__ === ''off'' ? 0.25 : (datum.__selected__ === ''on'' ? 1 : (datum.rank === 1 ? 1 : 0.62))"
     }
    }
   }
  },
  {
   "name": "rankText",
   "type": "text",
   "from": {
    "data": "top"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH + rowH / 2"
     },
     "text": {
      "signal": "datum.rank"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsRow"
     },
     "fontWeight": {
      "value": 600
     },
     "opacity": {
      "signal": "datum.__selected__ === ''off'' ? 0.35 : 1"
     }
    }
   }
  },
  {
   "name": "labelText",
   "type": "text",
   "from": {
    "data": "top"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "pad + rankW"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH + rowH / 2"
     },
     "text": {
      "signal": "datum.listLabel"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cText"
     },
     "fontSize": {
      "signal": "fsRow"
     },
     "fontWeight": {
      "signal": "datum.rank === 1 ? 700 : 500"
     },
     "limit": {
      "signal": "labelW - 6"
     },
     "opacity": {
      "signal": "datum.__selected__ === ''off'' ? 0.35 : 1"
     }
    }
   }
  },
  {
   "name": "valueText",
   "type": "text",
   "from": {
    "data": "top"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "valueRightX"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH + rowH / 2"
     },
     "text": {
      "signal": "datum.valueText"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cText"
     },
     "fontSize": {
      "signal": "fsRow"
     },
     "fontWeight": {
      "value": 600
     },
     "opacity": {
      "signal": "datum.__selected__ === ''off'' ? 0.35 : 1"
     }
    }
   }
  },
  {
   "name": "shareText",
   "type": "text",
   "from": {
    "data": "top"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width - pad"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH + rowH / 2"
     },
     "text": {
      "signal": "showShare ? datum.shareText : ''''"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     },
     "opacity": {
      "signal": "datum.__selected__ === ''off'' ? 0.35 : 1"
     }
    }
   }
  },
  {
   "name": "hitRows",
   "type": "rect",
   "from": {
    "data": "top"
   },
   "encode": {
    "enter": {
     "fill": {
      "value": "#FFFFFF"
     },
     "cursor": {
      "value": "pointer"
     }
    },
    "update": {
     "x": {
      "signal": "pad - 6"
     },
     "y": {
      "signal": "topY + (datum.rank - 1) * rowH"
     },
     "width": {
      "signal": "innerW + 12"
     },
     "height": {
      "signal": "rowH"
     },
     "cornerRadius": {
      "value": 6
     },
     "fillOpacity": {
      "value": 0
     },
     "tooltip": {
      "signal": "{''Posição'': ''#'' + datum.rank, ''Município'': datum.muniTxt, ''Estado'': datum.estadoTxt, ''Focos'': pbiFormat(datum.focos, ''#,0''), ''% do total'': pbiFormat(datum.share, ''0.0%''), ''% do líder'': pbiFormat(datum.vsLeader, ''0%'')}"
     }
    },
    "hover": {
     "fillOpacity": {
      "value": 0.06
     }
    }
   }
  },
  {
   "name": "footer",
   "type": "text",
   "from": {
    "data": "foot"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "pad"
     },
     "y": {
      "signal": "height - pad - 3"
     },
     "text": {
      "signal": "showFooter ? datum.text : ''''"
     },
     "baseline": {
      "value": "bottom"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "fsMicro"
     },
     "limit": {
      "signal": "innerW"
     }
    }
   }
  },
  {
   "name": "emptyMessage",
   "type": "text",
   "from": {
    "data": "emptyState"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width / 2"
     },
     "y": {
      "signal": "height / 2"
     },
     "text": {
      "signal": "length(data(''dataset'')) > 0 ? ''Adicione o campo município ao visual'' : ''Sem dados para o contexto selecionado''"
     },
     "align": {
      "value": "center"
     },
     "baseline": {
      "value": "middle"
     },
     "fill": {
      "signal": "cTextMuted"
     },
     "fontSize": {
      "signal": "max(12, 14 * fs)"
     },
     "limit": {
      "signal": "max(0, width - 2 * pad)"
     }
    }
   }
  }
 ]
}'

'{
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "view": {
    "stroke": "transparent"
  },
  "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
  "arc": {},
  "area": {
    "line": true,
    "opacity": 0.6
  },
  "bar": {},
  "line": {
